using System;using System.IO;using System.Reflection;using System.Collections.Generic;using SargasPC;
class RecoveryTests{
 static int n; static void Check(bool x){if(!x)throw new Exception("check "+n);n++;}
 static void Scope(Core c,Witness w, bool incomplete){typeof(Core).GetMethod("ApplyEngineScope",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{w,new LocalEngineVerdict{Incomplete=incomplete,Scanned=1}});}
 static void Main(){string root=Path.Combine(Path.GetTempPath(),"sargon32-"+Guid.NewGuid());try{var c=new Core(root);var w=new Witness{Path="neutral.docx",Hash=new string('a',64),Archive="ZIP metadata"};c.Describe(w,new HashSet<string>());Check(c.NotChecked==1&&c.ArchiveReviews==1);Check(c.Outcome(true)=="APIMTIS NEUŽBAIGTA");Scope(c,w,false);Check(c.NotChecked==0&&c.LocalEngineCompleted==1);Check(c.Outcome(true).Contains("CLAMAV PATIKRA BAIGTA"));Check(c.Metrics(1,1).Contains("peržiūros: 1"));Scope(c,w,false);Check(c.NotChecked==0);c.NotChecked++;Check(c.Outcome(true)=="APIMTIS NEUŽBAIGTA");Check(c.Outcome(false).Contains("NEPATVIRTINTAS"));c.EngineFindings++;Check(c.Outcome(true)=="ANTIVIRUSINIO VARIKLIO RADINYS");c.Reset();Check(c.NotChecked==0&&c.LocalEngineCompleted==0&&c.ArchiveReviews==0);w=new Witness{Path="encrypted.zip",Hash=new string('b',64),Archive="ZIP metadata"};c.Describe(w,new HashSet<string>());Scope(c,w,true);Check(c.NotChecked==2&&c.LocalEngineCompleted==0);Check(c.Outcome(true)=="APIMTIS NEUŽBAIGTA");c.Reset();w=new Witness{Path="plain.txt",Hash=new string('c',64)};c.Describe(w,new HashSet<string>());Scope(c,w,false);Check(c.NotChecked==0&&c.LocalEngineCompleted==1);Check(c.Outcome(true).Contains("CLAMAV"));Check(ShieldPanel.Resolve(false,false,"SCAN_COMPLETED",0,0)=="scanned");Check(ShieldPanel.Resolve(false,true,"SCAN_COMPLETED",0,0)=="warning");Check(ShieldPanel.Resolve(false,false,"SCAN_COMPLETED",1,0)=="detected");Check(ShieldPanel.Resolve(false,false,"SCAN_COMPLETED",0,1)=="test");var clean=LocalEngine.Parse(new CommandOutput{ExitCode=0,Output="Scanned files: 1\n",Error=""});Check(!clean.Found&&!clean.Incomplete);var limit=LocalEngine.Parse(new CommandOutput{ExitCode=1,Output="x: Heuristics.Limits.Exceeded.MaxFileSize FOUND\nScanned files: 1\n",Error=""});Check(!limit.Found&&limit.Incomplete);var encrypted=LocalEngine.Parse(new CommandOutput{ExitCode=1,Output="x: Heuristics.Encrypted.Zip FOUND\nScanned files: 1\n",Error=""});Check(!encrypted.Found&&encrypted.Incomplete);var found=LocalEngine.Parse(new CommandOutput{ExitCode=1,Output="x: Controlled.Test FOUND\nScanned files: 1\n",Error=""});Check(found.Found&&!found.Incomplete);Check(Data.CleanLog("a\nb")=="a\r\nb");Console.WriteLine("PASS: "+n+" recovery checks; no native Windows or malware efficacy test.");}finally{Directory.Delete(root,true);}}
}
